import json, pathlib, sys, time
marker = pathlib.Path(sys.argv[1])
def identity(pid):
    try:
        value = pathlib.Path('/proc', str(pid), 'stat').read_text().rpartition(') ')[2].split()
        return int(value[19])
    except (FileNotFoundError, ProcessLookupError):
        return None
while not marker.exists():
    time.sleep(0.05)
